        if i != j:
            p1 = place_list[i]
            p2 = place_list[j]
            t_travel = travel_times[p1][p2]
            s.add(
                Implies(
                    And(is_visited[p1], is_visited[p2]),
                    Or(
                        end_time[p1] + t_travel <= start_time[p2],
                        end_time[p2] + travel_times[p2][p1] <= start_time[p1],
